graph = {
    "A": ["B", "C"],
    "B": ["A", "D", "E"],
    "C": ["A", "F"],
    "D": ["B"],
    "E": ["B", "F"],
    "F": ["C", "E"],
}

def dfs(graph, k, besucht=None):
    if besucht is None:
        besucht = []
    besucht.append(k)
    for n in graph[k]:
        if n not in besucht:
            dfs(graph, n, besucht)
    return besucht

print(dfs(graph, "A"))
# ['A', 'B', 'D', 'E', 'F', 'C']

graph = {
    "A": ["B", "C"],
    "B": ["A", "D", "E"],
    "C": ["A", "F"],
    "D": ["B"],
    "E": ["B", "F"],
    "F": ["C", "E"],
}
from collections import deque

def weg(graph, start, ziel):
    vorg = {start: None}
    queue = deque([start])
    while queue:
        k = queue.popleft()
        for n in graph[k]:
            if n not in vorg:
                vorg[n] = k
                queue.append(n)
    if ziel not in vorg:
        return None   # nicht erreichbar
    pfad = []
    while ziel is not None:
        pfad.append(ziel)
        ziel = vorg[ziel]
    return pfad[::-1]

print(weg(graph, "D", "F"))
# ['D', 'B', 'E', 'F']
